    tid=os.path.basename(tf)[:-3]
    jf=ws+'/'+tid+'.json'
    if not os.path.exists(jf): continue
    spec=importlib.util.spec_from_file_location(tid, tf); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    pairs=json.load(open(jf))
    try:
        results[tid]=all(mod.transform(p['input'])==p['output'] for p in pairs)
    except Exception as e:
        results[tid]='ERR '+repr(e)
for k,v in results.items(): print(k,v)
